const upd = $('Telegram Trigger1').first().json || {};
const msg = upd.message || {};
const rawText = String(msg.text || msg.caption || '');

const norm = s => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
const stripUrls = s => String(s || '').replace(/https?:\/\/\S+/gi, ' ');

// Single value: new lines become spaces, extra spaces and trailing commas are removed
const flat = v => String(v == null ? '' : v)
  .replace(/\r?\n+/g, ' ')
  .replace(/\s+/g, ' ')
  .replace(/^[\s,]+|[\s,]+$/g, '');

// Comma separated list. Commas inside brackets "( )" and inside numbers like 50,000 do not split.
const splitList = val => {
  const t = String(val == null ? '' : val).replace(/\r?\n+/g, ' ');
  const out = [];
  let depth = 0, cur = '';
  for (let i = 0; i < t.length; i++) {
    const ch = t[i];
    if (ch === '(' || ch === '[') depth++;
    if (ch === ')' || ch === ']') depth = Math.max(0, depth - 1);
    const numComma = ch === ',' && /\d/.test(t[i - 1] || '') && /\d/.test(t[i + 1] || '');
    if (ch === ',' && depth === 0 && !numComma) { out.push(cur); cur = ''; }
    else cur += ch;
  }
  out.push(cur);
  return out.map(x => x.replace(/\s+/g, ' ').trim()).filter(Boolean);
};

// Hashtag list: separated by commas or spaces
const splitTags = val => String(val == null ? '' : val).split(/[\s,]+/).map(x => x.trim()).filter(Boolean);

// Data table column names are trimmed and lowercased ("brand_id " becomes "brand_id")
const rows = $('Fetch Brands from Data Table').all().map(it => {
  const o = {};
  for (const [k, v] of Object.entries(it.json || {})) o[String(k).trim().toLowerCase().replace(/\s+/g, '_')] = v;
  return o;
}).filter(r => flat(r.brand_id) || flat(r.brand_name || r.bard_name || r.name));

const nameOf = r => flat(r.brand_name || r.bard_name || r.name);

// "/brand x" or "brand: x" matches by id or name. Free text matches by name (and non-numeric ids).
const em = rawText.match(/\/brand(?:@\w+)?\s+([^\n]*)/i) || rawText.match(/\bbrand\s*:\s*([^\n]*)/i);
const useIds = !!em;
const phrase = ' ' + norm(stripUrls(em ? em[1] : rawText)) + ' ';

let r = null, best = 0;
for (const row of rows) {
  const cands = [nameOf(row)];
  const id = flat(row.brand_id);
  if (id && (useIds || !/^\d+$/.test(id))) cands.push(id);
  for (const c of cands) {
    const n = norm(c);
    if (n && phrase.includes(' ' + n + ' ') && n.length > best) { r = row; best = n.length; }
  }
}

const x = r || {};
const BRAND = {
  brand_id: flat(x.brand_id).toLowerCase(),
  brand_name: nameOf(x),
  namelink: flat(x.link || x.namelink || x.website),
  instagram_handle: flat(x.ig_id || x.instagram_handle || x.ig_handle),
  industry: flat(x.industry),
  about: flat(x.about),
  products_services: splitList(x.products_services),
  usps: splitList(x.usps),
  target_audience: flat(x.target_audience),
  audience_age: flat(x.audience_age),
  audience_interests: splitList(x.audience_interests),
  city: flat(x.city),
  state: flat(x.state),
  country: flat(x.country),
  service_area: flat(x.service_area),
  goal: flat(x.goal),
  tone: flat(x.tone),
  caption_language: flat(x.caption_language) || 'English',
  default_cta: flat(x.default_cta),
  always_include_hashtags: splitTags(x.always_include_hashtags),
  never_use_hashtags: splitTags(x.never_use_hashtags),
  notes: flat(x.notes)
};

const brand = {};
for (const [k, v] of Object.entries(BRAND)) {
  if (Array.isArray(v) && v.length) brand[k] = v;
  else if (typeof v === 'string' && v) brand[k] = v;
}

return [{ json: {
  brand,
  found: !!r,
  available: rows.map(row => nameOf(row) || flat(row.brand_id)).filter(Boolean)
} }];

const upd = $('Telegram Trigger1').first().json || {};
const msg = upd.message;
if (!msg || !msg.chat || (msg.from && msg.from.is_bot) || msg.chat.type !== 'private') return [];

const chatId = msg.chat.id;
const ALLOWED_CHAT_IDS = [7009284089, 841863295];
const COOLDOWN_SEC = 20;

if (ALLOWED_CHAT_IDS.length && !ALLOWED_CHAT_IDS.includes(chatId)) return [];

const text = (msg.text || '').trim();
const caption = (msg.caption || '').trim();

// LANGUAGE RULE:
// Only lang:hinglish enables Hinglish descriptions.
// Every other value, including missing language, defaults to English.
const incomingText = [text, caption].filter(Boolean).join('\n');
const langMatch = incomingText.match(/\blang\s*:\s*([a-z-]+)/i);
const descriptionLanguage =
  langMatch && langMatch[1].toLowerCase() === 'hinglish'
    ? 'hinglish'
    : 'english';

// Remove language directives so they do not become part of the
// brand brief, script, or media-analysis instructions.
const cleanLanguageDirective = value =>
  String(value || '')
    .replace(/\blang\s*:\s*[a-z-]+\b/gi, ' ')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/ *\n */g, '\n')
    .trim();

const cleanText = cleanLanguageDirective(text);
const cleanCaption = cleanLanguageDirective(caption);

const store = $getWorkflowStaticData('global');
store.profiles = store.profiles || {};
store.last = store.last || {};
const profile = store.profiles[chatId] || '';

let brandMeta = {};
try { brandMeta = $('Brand Config').first().json || {}; } catch (e) { brandMeta = {}; }
const brandFound = !!brandMeta.found;
const brandList = (brandMeta.available || []).join(', ');

const esc = v => String(v == null ? '' : v)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;');

const reply = (t, extra = {}) => [{
  json: {
    action: 'reply',
    chat_id: chatId,
    text: t,
    media: null,
    mode: null,
    answers: null,
    drive: null,
    ...extra,
  }
}];

function detectMedia(m) {
  if (!m) return null;

  if (m.photo && m.photo.length) {
    const p = m.photo[m.photo.length - 1];
    return {
      kind: 'image',
      file_id: p.file_id,
      mime: 'image/jpeg',
      size: p.file_size || 0
    };
  }

  if (m.video || m.animation || m.video_note) {
    return { kind: 'video' };
  }

  if (m.document) {
    const mt = m.document.mime_type || '';

    if (mt.startsWith('image/')) {
      return {
        kind: 'image',
        file_id: m.document.file_id,
        mime: mt,
        size: m.document.file_size || 0
      };
    }

    if (mt.startsWith('video/')) {
      return { kind: 'video' };
    }
  }

  return null;
}

function analyze(mode, media, details, note = '', drive = null) {
  if (!brandFound) {
    return reply(
      'Brand not found. Please send the brand name along with your post.\n' +
      'Available brands: ' + esc(brandList || 'none') +
      '\nExample:\n<pre>achiwon https://drive.google.com/drive/folders/XXXX</pre>'
    );
  }

  const now = Date.now();

  if (now - (store.last[chatId] || 0) < COOLDOWN_SEC * 1000) {
    return reply(
      'Please wait about ' + COOLDOWN_SEC +
      ' seconds before sending the next post.'
    );
  }

  store.last[chatId] = now;

  const msgText = mode === 'text'
    ? 'Your script is being analysed. This usually takes 10 to 20 seconds.'
    : mode === 'drive'
      ? 'Your Drive folder is being downloaded and analysed. Images take about 1 to 3 minutes. A video can take a few minutes longer.'
      : 'Your image is being analysed. This usually takes 15 to 30 seconds.';

  return reply(
    (note ? note + '\n\n' : '') + msgText,
    {
      action: 'analyze',
      mode,
      media,
      drive,
      answers: {
        details: String(details || '').slice(0, 4000),
        language: descriptionLanguage
      }
    }
  );
}

const cmd = text.startsWith('/')
  ? text.split(/[\s@]/)[0].toLowerCase()
  : '';

if (cmd === '/start' || cmd === '/help') {
  return reply(
    'Send a Google Drive folder link (images only, 1 video only, or images plus 1 video) or a single image together with the brand name.\n' +
    'Example: achiwon https://drive.google.com/drive/folders/XXXX\n' +
    'For reels: /reel achiwon followed by the script.\n' +
    'For Hinglish descriptions, include lang:hinglish.\n' +
    'Without that directive, descriptions are in English.\n' +
    'Available brands: ' + esc(brandList || 'none')
  );
}

// Reel script: "/reel ...", "reel ..." (slash forgotten),
// or any long plain-text message.
const DRIVE_RE_EARLY = /https?:\/\/drive\.google\.com\//i;
const hasOwnMedia = !!detectMedia(msg);
const isReelCmd = cmd === '/reel' || /^reel\b/i.test(text);
const isPlainScript =
  !cmd &&
  !hasOwnMedia &&
  !DRIVE_RE_EARLY.test(text) &&
  text.length >= 30;

if (isReelCmd || isPlainScript) {
  const body = cleanText.replace(/^\/?reel(@\w+)?/i, '').trim();

  if (body.length < 30) {
    return reply(
      'Script is too short. Send it like:\n' +
      '<pre>/reel achiwon your script here</pre>'
    );
  }

  return analyze(
    'text',
    null,
    profile ? profile + '\n' + body : body
  );
}

const ownMedia = detectMedia(msg);
const DRIVE_RE =
  /https?:\/\/drive\.google\.com\/(?:drive\/(?:u\/\d+\/)?folders\/|file\/d\/)([A-Za-z0-9_-]{10,})\S*/i;

const linkSource = text || caption;
const dm = DRIVE_RE.exec(linkSource);

if (dm && !ownMedia) {
  const kind = /\/folders\//i.test(dm[0]) ? 'folder' : 'file';

  if (kind !== 'folder') {
    return reply('Please send a Google Drive folder link (not a single file link).');
  }

  const extra = cleanLanguageDirective(
    linkSource.replace(dm[0], '')
  ).trim();

  const details = profile
    ? profile + (extra ? '\n' + extra : '')
    : extra;

  return analyze(
    'drive',
    null,
    details,
    '',
    { kind, id: dm[1] }
  );
}

const media = ownMedia || detectMedia(msg.reply_to_message);

if (media) {
  if (media.kind === 'video') {
    return reply('Video direct analysis not supported. Use /reel.');
  }

  const extra = ownMedia ? cleanCaption : cleanText;
  const details = profile
    ? profile + (extra ? '\n' + extra : '')
    : extra;

  return analyze('image', media, details);
}

return reply(
  'Please send an image, Drive link, or /reel script.\n' +
  '(Received: ' +
  (text ? text.length + ' characters of text' : 'no text or supported media') +
  ')'
);

const MAX_SLIDES = 8;
const MAX_IMAGE_BYTES = 2 * 1024 * 1024;

const safe = fn => { try { return fn(); } catch (e) { return null; } };
// Only present on the Drive path. Telegram photos never pass through the classifier.
const cls = safe(() => $('Classify Drive Files').first().json) || {};
const selected = cls.images || [];
const overLimit = cls.images_over_limit || [];
const order = new Map(selected.map((f, i) => [f.name, i]));

const items = $input.all();
const entries = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  const bin = it.binary && it.binary.data;
  const fileName = (bin && bin.fileName) || '';
  const name = fileName || ('item ' + (i + 1));
  entries.push({ i, bin, name, key: order.has(name) ? order.get(name) : 999 });
}
// keep the folder order (alphabetical)
entries.sort((x, y) => (x.key - y.key) || (x.i - y.i));

const slides = [];
const skipped = [];

for (const e of entries) {
  const kind = 'image';
  if (!e.bin) { skipped.push({ name: e.name, kind, reason: 'file could not be read' }); continue; }
  if (slides.length >= MAX_SLIDES) { skipped.push({ name: e.name, kind, reason: 'over the ' + MAX_SLIDES + '-item limit' }); continue; }
  const buf = await this.helpers.getBinaryDataBuffer(e.i, 'data');
  if (buf.length > MAX_IMAGE_BYTES) { skipped.push({ name: e.name, kind, reason: 'larger than 2 MB after resize' }); continue; }
  const mime = e.bin.mimeType || 'image/jpeg';
  slides.push({ slide_no: slides.length + 1, name: e.name, kind, mime, data_url: 'data:' + mime + ';base64,' + buf.toString('base64') });
}

// Images that were listed but not downloaded (folder has more than the limit)
for (const f of overLimit) {
  skipped.push({ name: f.name, kind: 'image', reason: 'over the ' + MAX_SLIDES + '-item limit' });
}

return [{ json: { slides, skipped_items: skipped, counts: { total_items: slides.length + skipped.length } } }];

const s = $('Session Manager1').first().json;
const item = $input.first();
const a = s.answers || {};
const isText = s.mode === 'text';
const brand = $('Brand Config').first()?.json?.brand || {};

const safeStr = v => v == null ? '' : String(v).trim();

const list = v => {
  if (Array.isArray(v)) return v.map(safeStr).filter(Boolean);
  if (typeof v === 'string') {
    return v.split(/[,;\n]/).map(x => x.trim()).filter(Boolean);
  }
  return [];
};

const hasValue = v => {
  if (Array.isArray(v)) return v.some(hasValue);
  if (v && typeof v === 'object') return Object.values(v).some(hasValue);
  return v !== null && v !== undefined && safeStr(v) !== '';
};

const compactValue = v => {
  if (Array.isArray(v)) return v.map(compactValue).filter(hasValue);
  if (!v || typeof v !== 'object') return v;
  return Object.fromEntries(
    Object.entries(v)
      .filter(([, value]) => hasValue(value))
      .map(([key, value]) => [key, compactValue(value)])
  );
};

const jsonForPrompt = v => JSON.stringify(compactValue(v));

const brandContext = compactValue({
  brand_name: brand.brand_name,
  instagram_handle: brand.instagram_handle,
  industry: brand.industry,
  about: brand.about,
  products_services: brand.products_services,
  usps: brand.usps,
  target_audience: brand.target_audience,
  audience_age: brand.audience_age,
  audience_interests: brand.audience_interests,
  city: brand.city,
  state: brand.state,
  country: brand.country,
  service_area: brand.service_area,
  audience_geography: brand.audience_geography,
  goal: brand.goal,
  tone: brand.tone,
  caption_language: brand.caption_language,
  default_cta: brand.default_cta,
  always_include_hashtags: list(brand.always_include_hashtags),
  never_use_hashtags: list(brand.never_use_hashtags),
  notes: brand.notes
});

const media = compactValue({
  phase1_done: item.json.phase1_done,
  slides_ok: item.json.slides_ok,
  video_analysis: item.json.video_analysis,
  report: item.json.report
});

const contentType =
  safeStr(a.post_type || a.content_type || a.postType) ||
  safeStr(a.content_goal || a.goal) ||
  safeStr(brand.goal) ||
  'social media post';

const SYSTEM_MEDIA = `
You are a social-media caption and organic-discovery specialist for multiple brands, industries and content formats.

CORE PRIORITY
Make the caption feel human and scroll-stopping first; SEO second. The caption must relate to the actual media, attract the right viewer and give them a reason to keep reading or engage. Match emotional intensity to the content; never force drama into calm or practical posts.

1. SOURCE AND ACCURACY
Prioritize actual image/video/slide analysis, then brand information and the user brief. Respect the post type, topic, language, audience, goal and brand voice. Never invent visual details, product features, ingredients, results, prices, statistics, offers, testimonials, credentials, personal experiences or claims. Do not describe unseen content as verified. Use only relevant brand facts.

2. HOOK AND CURIOSITY
The opening must be specific to this post, not a reusable generic line. Find the strongest supported angle: an unexpected detail, meaningful contrast, relatable problem, overlooked point, surprising-but-true observation, practical payoff, common mistake, useful question or unresolved curiosity. Choose an angle the content can genuinely deliver on.

Give viewers a reason to pause, read more or watch closely. Use a curiosity gap when appropriate and deliver its payoff. Avoid clickbait, bland introductions, generic questions, empty hype, obvious statements and repetitive hook formulas. Do not always start with a question or use the same hook style across posts.

For Reels, use the actual scene, action, demonstration, transformation or central idea. For images, use the strongest visible detail or message. For carousels, use the overall takeaway, a useful slide detail or a reason to explore the slides. Adapt to the real format.

3. HUMAN-FEEL CHECKLIST
Before finalizing, internally check:
- Does the first line make this specific post worth noticing?
- Is there a clear curiosity, relevance, contrast or benefit?
- Does it sound like a person speaking to one viewer?
- Is the rhythm natural, with varied sentence lengths?
- Is the wording concrete rather than vague or corporate?
- Does the emotional tone fit the actual content?
- Does every claim follow from the media, brief or brand facts?
- Does the caption offer a clear takeaway or meaningful connection?
- Does the ending/CTA feel natural rather than mechanically attached?
- Do consecutive lines flow naturally into each other?
- Does the caption avoid common AI patterns such as overly balanced paragraphs, repetitive sentence openings and overly formal transitions?

Improve weak points before returning the result. Do not expose this checklist.

4. HUMAN VOICE, FLOW AND STRUCTURE
Use natural conversational language, personal pronouns and relatable wording when appropriate. Sensory language is allowed only when supported. Avoid corporate brochures, AI essays, motivational-poster language, forced emotions, filler, clichés, keyword stuffing and over-polished explanations.

Write with natural spoken flow. Each new line should continue the previous thought, not feel like a separate point. Prefer short-to-medium sentences that connect smoothly. Avoid starting consecutive lines with the same word or structure. Line breaks should create rhythm and breathing space, not chop the caption into disconnected statements.

Choose the structure that fits the post: a short punchy caption, curiosity-led opening with payoff, relatable situation, practical insight, mini-story, concise explanation or another suitable format. These are options, not templates. Do not force a story, educational list, dramatic reveal or long explanation into every post. Keep length proportionate to the media and message. Use 0–2 relevant emojis only when they fit the brand voice.

5. AUDIENCE AND CTA
Write for the brand's actual target audience, interests, age range and geography when provided. Prefer relevance over appealing to everyone. Use the requested language and brand tone. A CTA should support the post goal and invite a natural next step: reflect, save, share, comment, explore or buy only when relevant. Use the brand's default CTA when suitable; never force engagement bait.

6. SEO KEYWORDS — EXACTLY 10
Return 10 distinct search phrases relevant to the actual post and brand. Aim for:
- 3–4 specific topic, subject, product or service phrases.
- 3–4 audience-intent, need, question or problem-aware phrases.
- 2–3 broader but still relevant discovery phrases.

These ranges must total exactly 10. Use natural phrases a relevant viewer might search for, aligned with the actual media, brand and audience. Avoid near-duplicates, unrelated high-volume terms and unsupported claims. Do not mechanically repeat the same keyword pattern for every brand.

7. HASHTAGS AND DISCOVERY
Return exactly 5 recommended hashtags and 10 additional hashtags in the required output fields. Mix specific niche/community tags, relevant subject or product tags, audience-interest tags and broader discovery tags where appropriate. Prefer tags that real accounts in the same niche actually use, when known. Never claim a tag is trending, viral or high-volume without verified research.

Prioritize relevance to the post and intended audience, not popularity alone. Avoid irrelevant generic tag piles, misleading tags, duplicates across hashtag groups and forbidden tags. Respect required and prohibited brand hashtag lists. Include required tags where relevant and never use forbidden ones.

Location tags belong only in hashtags.location_tags and only when a specific city or state is supplied and genuinely relevant. Return an empty array when location tags are not justified. Never infer location from language, industry or audience alone. Never guarantee reach, views, virality or ranking.

8. FINAL VALIDATION
Verify before returning:
- Caption is media-related, specific, curiosity-building where suitable, readable and human.
- Lines connect smoothly; sentence openings and structure do not feel repetitive or mechanically balanced.
- Emotional intensity fits the content.
- Keywords contain exactly 10 distinct relevant phrases with the intended mix.
- hashtags.recommended_5 contains exactly 5 hashtags.
- hashtags.extra_pool contains exactly 10 additional hashtags.
- hashtags.location_tags contains only justified location tags or an empty array.
- Hashtags are correctly formatted, duplicates are removed and forbidden tags are excluded.
- Brand tone, language, user brief and factual accuracy are respected.
- JSON keys and nesting match the required schema exactly.

OUTPUT CONTRACT
Return only one valid JSON object:
{
  "caption": "string",
  "keywords": ["10 keyword phrases"],
  "hashtags": {
    "recommended_5": ["5 hashtags"],
    "extra_pool": ["10 hashtags"],
    "location_tags": []
  }
}

Do not add Markdown, explanations or extra keys. Use the requested language; if unspecified, use brand.caption_language, then infer from the user brief.
`.trim();

const promptData = compactValue({
  task: 'Generate a final social-media caption and organic-discovery metadata.',
  content_type: contentType,
  requested_language:
    safeStr(a.caption_language || a.language || brand.caption_language),
  topic: a.topic,
  reference: a.reference || a.reference_link || a.ref,
  concept: a.concept,
  instructions: a.instructions || a.additional_instructions,
  content_goal: a.content_goal || a.goal || brand.goal,
  brand: brandContext,
  media_analysis: isText ? undefined : media,
  text_content: isText
    ? (a.text || a.content || item.json.text || item.json.content)
    : undefined,
  priorities: [
    'Media-specific curiosity and viewer relevance',
    'Human voice, smooth flow and natural line breaks',
    'No forced drama, clickbait or generic AI patterns',
    'Right-audience discovery through relevant keywords and hashtags',
    'Truthful claims and brand consistency',
    'Exact original JSON schema and item counts'
  ]
});

const body = {
  model: 'openai/gpt-oss-120b',
  temperature: 0.55,
  max_completion_tokens: isText ? 3000 : 2500,
  reasoning_effort: 'low',
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: SYSTEM_MEDIA },
    {
      role: 'user',
      content: jsonForPrompt(promptData)
    }
  ]
};

return {
  phase: 'final',
  body,
  report: item.json.report || {},
  _debug: {
    mode: isText ? 'text' : 'media',
    contentType,
    promptVersion: 'human-discovery-v2-flow-optimized'
  }
};

const s = $('Session Manager1').first().json;
let brand = {};
try { brand = $('Brand Config').first().json.brand || {}; } catch (e) { brand = {}; }
const res = $input.first().json;

const cand = res && res.choices && res.choices[0];
let raw = (cand && cand.message && cand.message.content) || '';
raw = String(raw).replace(/<think>[\s\S]*?<\/think>/gi, '').trim();
if (!raw) throw new Error('USER: The model returned an empty response. Please try again.');

let d;
try {
  const i = raw.indexOf('{');
  const j = raw.lastIndexOf('}');
  d = JSON.parse(i >= 0 && j > i ? raw.slice(i, j + 1) : raw);
} catch (e) {
  throw new Error('USER: The response could not be read. Please resend your request.');
}

const esc = v => String(v == null ? '' : v).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const arr = v => (Array.isArray(v) ? v.filter(Boolean) : []);

// ---------- Hashtags ----------
const cleanTag = t => String(t == null ? '' : t).trim().replace(/[^\p{L}\p{N}_#]/gu, '').replace(/^#+/, '');
const tag = t => { const c = cleanTag(t); return c ? '#' + c : ''; };
const blocked = new Set(arr(brand.never_use_hashtags).map(t => tag(t).toLowerCase()).filter(Boolean));
const seen = new Set();
const tags = list => arr(list).map(tag).filter(t => {
  const k = t.toLowerCase();
  if (!t || blocked.has(k) || seen.has(k)) return false;
  seen.add(k);
  return true;
});

const f = d.final || d;
const h = f.hashtags || {};

// brand tags are registered first so the model's tags cannot duplicate them
const branded = tags(brand.always_include_hashtags);
const recommended = tags(h.recommended_5);
const location = tags(h.location_tags);
const extra = tags(h.extra_pool);

// ---------- Caption cleanup ----------
const websiteLink = String(brand.namelink || '').trim();

let caption = String(f.caption || '')
  .replace(/^[ \t]*[\u2705\u2714\u2611]\uFE0F?[ \t]*/gmu, '• ')
  .replace(/[\u2705\u2714\u2611\u274C\u{1F680}\u{1F525}\u{1F4AF}]\uFE0F?/gu, '')
  .replace(/(?:https?:\/\/|www\.)\S+/gi, '')
  .replace(/(^|\s)#[\p{L}\p{N}_]+/gu, '$1')
