    responseMimeType: 'application/json'
  }
};

return [{
  json: {
    gemini_model: GEMINI_MODEL,
    gemini_body: body
  }
}];

// Parses the Gemini video analysis and merges it with the image results (if the folder also had images).
const clip = (v, n) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n);
const cls = $('Classify Drive Files').first().json;
const res = $input.first().json || {};

const cand = res.candidates && res.candidates[0];
const raw = ((cand && cand.content && cand.content.parts) || []).filter(p => !p.thought).map(p => p.text || '').join('').trim();
if (!raw) {
  const why = (res.promptFeedback && res.promptFeedback.blockReason) || (cand && cand.finishReason);
  throw new Error('USER: The video could not be analysed' + (why ? ' (' + why + ')' : '') + '. Please try a different video.');
}
let p;
try {
  const a = raw.indexOf('{'), z = raw.lastIndexOf('}');
  p = JSON.parse(a >= 0 && z > a ? raw.slice(a, z + 1) : raw);
} catch (e) {
  throw new Error('USER: The video analysis could not be read. Please try again.');
}
const v = p.video || p;
const video = {
  summary: clip(v.summary, 700),
  scenes: (Array.isArray(v.scenes) ? v.scenes : []).slice(0, 8).map(s => ({ time: clip(s && s.time, 12), shows: clip(s && s.shows, 200) })),
  text_on_screen: clip(v.text_on_screen || 'none', 600),
  spoken_content: clip(v.spoken_content || 'no speech', 700),
  key_message: clip(v.key_message, 300),
  visual_style: clip(v.visual_style, 300)
};
if (!video.summary && !video.key_message) throw new Error('USER: The video analysis was empty. Please try again.');

let prior = {};
if (cls.has_images) prior = $('Collect Slide Results').first().json || {};
const base = prior.report || { total: 0, processed: 0, images_ok: 0, videos_ok: 0, failed_skipped: 0, models: {}, issues: [] };
const report = JSON.parse(JSON.stringify(base));
report.total += 1;
report.processed += 1;
report.videos_ok = 1;
report.video_attempted = true;
report.models = Object.assign({}, report.models, { gemini_file: 1 });
(cls.videos_ignored || []).forEach(n => {
  report.total += 1;
  report.failed_skipped += 1;
  report.issues.push(clip(n + ' (video): skipped - only 1 video is analysed per folder', 160));
});

return [{ json: { phase1_done: true, slides_ok: prior.slides_ok || [], video_analysis: video, report } }];

// Any failure in the video path lands here.
//  - Video-only folder: the whole run fails, Build Error Message explains why.
//  - Folder with images + 1 video: keep the image results and list the video under "Not included".
const clip = (v, n) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, n);
const cls = $('Classify Drive Files').first().json;
const j = $input.first().json || {};
const raw = (j.error && (j.error.message || j.error.description)) || j.error || j.message || 'Unknown error';
const msg = String(typeof raw === 'string' ? raw : JSON.stringify(raw));

if (!cls.has_images) throw new Error(msg);

const prior = $('Collect Slide Results').first().json || {};
const report = JSON.parse(JSON.stringify(prior.report || { total: 0, processed: 0, images_ok: 0, videos_ok: 0, failed_skipped: 0, models: {}, issues: [] }));
const u = msg.indexOf('USER: ');
const why = u >= 0 ? msg.slice(u + 6).split('\n')[0] : msg;
report.total += 1;
report.failed_skipped += 1;
report.video_attempted = true;
report.issues.push(clip(((cls.video && cls.video.name) || 'video') + ' (video): not analysed - ' + why, 200));
(cls.videos_ignored || []).forEach(n => {
  report.total += 1;
  report.failed_skipped += 1;
  report.issues.push(clip(n + ' (video): skipped - only 1 video is analysed per folder', 160));
});
return [{ json: { phase1_done: true, slides_ok: prior.slides_ok || [], video_analysis: null, report } }];
